14	/**
15	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
16	 * so tests can assert side-effects by reading that file — the second test-assertion channel
17	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
18	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
19	 *
20	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
21	 * SYNC) so a test reads the record immediately.
22	 */
23	@Service
24	public class Audit {
25	    private final Path file;
26	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
27	        this.file = Path.of(path);
28	    }
29	    /** Append one audit record. Tests assert the exact line(s) in the file. */
30	    public synchronized void record(String entry) {
31	        try {
32	            Path parent = file.toAbsolutePath().getParent();
33	            if (parent != null) {
34	                Files.createDirectories(parent);
35	            }
36	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
37	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
38	        } catch (IOException e) {
39	            throw new UncheckedIOException(e);
40	        }
41	    }
42	    /** Remove the audit file. */
43	    public synchronized void clear() {
44	        try {
45	            Files.deleteIfExists(file);
46	        } catch (IOException e) {
47	            throw new UncheckedIOException(e);
48	        }
49	    }
50	}
