52	/** Moves the claim to the action's status, refusing a change its current status does not allow.
53	 *  Opening gives the claim the sheet's next number; voiding clears it. Settling fixes the claim's
54	 *  due at the person's grade's rate in force on the claim's date (none when there is none, so it stays live).
55	 *  A claim a statement binds is settled at its bound figure.
56	 *  The user who opened a claim may not settle it (four eyes).
57	 *  Publishes the number the audit line carries (for a void, the number the claim had). */
58	public class ApplyClaimAction {
59	    public void apply(@Val ClaimAction action, @Val Claim claim, ClaimRepository repository,
60	            PersonRepository people, RateRepository rates, Out<ClaimNumber> numberOut,
61	            @RequestParam(value = "user", required = false) String user)
62	            throws InvalidClaimStatusException {
63	        if (!action.allowedFrom(claim.getStatus())) {
64	            throw new InvalidClaimStatusException(
65	                    "A " + claim.getStatus() + " claim cannot be moved to " + action.to() + ".");
66	        }
67	        if (action == ClaimAction.SETTLE && claim.getOpenedBy() != null && claim.getOpenedBy().equals(user)) {
68	            throw new InvalidClaimStatusException("The user who opened a claim cannot settle it.");
69	        }
70	        Integer had = claim.getNumber();
71	        claim.setStatus(action.to());
72	        switch (action) {
73	            case OPEN -> {
74	                claim.setNumber(repository.nextNumber(claim.getSheetId()));
75	                claim.setOpenedBy(user);
76	            }
77	            case VOID -> claim.setNumber(null);
78	            case SETTLE -> claim.setSettledDue(claim.isStated() ? claim.getStatedDue() : dueNow(claim, people, rates));
79	            default -> { }
80	        }
81	        numberOut.set(new ClaimNumber(action == ClaimAction.VOID ? had : claim.getNumber()));
82	    }
83	    /** amount × pct / 100, rounded half to even to two decimals; null when no rate is in force on the claim's date. */
84	    private static BigDecimal dueNow(Claim claim, PersonRepository people, RateRepository rates) {
85	        Person person = people.findById(claim.getSheetId(), claim.getPersonId());
86	        return Rate.inForce(rates.findBySheet(claim.getSheetId()), person.getGrade(), claim.getDate())
87	                .map(r -> claim.getAmount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
88	                .orElse(null);
89	    }
90	}
