227	public class ClaimRepository {
228	    private static final RowMapper<Claim> ROW = (rs, i) -> new Claim(rs.getLong("id"), rs.getString("sheet_id"),
229	            rs.getLong("person_id"), rs.getBigDecimal("amount"), rs.getDate("claim_date").toLocalDate(),
230	            rs.getString("note"), ClaimStatus.valueOf(rs.getString("status")),
231	            rs.getObject("claim_number", Integer.class), rs.getBigDecimal("settled_due"),
232	            rs.getString("opened_by"), rs.getBoolean("stated"), rs.getBigDecimal("stated_due"));
233	    private final JdbcTemplate jdbc;
234	    public ClaimRepository(JdbcTemplate jdbc) {
235	        this.jdbc = jdbc;
236	    }
237	    public List<Claim> findBySheet(String sheetId) {
238	        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? ORDER BY id DESC", ROW, sheetId);
239	    }
240	    public List<Claim> findByPerson(String sheetId, long personId) {
241	        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY id DESC", ROW, sheetId, personId);
242	    }
243	    public Claim findById(String sheetId, long id) {
244	        List<Claim> found = jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND id = ?", ROW, sheetId, id);
245	        return found.isEmpty() ? null : found.get(0);
246	    }
247	    public Claim create(String sheetId, long personId, BigDecimal amount, LocalDate date, String note) {
248	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
249	        jdbc.update(con -> {
250	            PreparedStatement ps = con.prepareStatement(
251	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note) VALUES (?, ?, ?, ?, ?)",
252	                    new String[] {"id"});
253	            ps.setString(1, sheetId);
254	            ps.setLong(2, personId);
255	            ps.setBigDecimal(3, amount);
256	            ps.setDate(4, Date.valueOf(date));
257	            ps.setString(5, note);
258	            return ps;
259	        }, keys);
260	        return new Claim(keys.getKey().longValue(), sheetId, personId, amount, date, note, ClaimStatus.DRAFT, null, null, null, false, null);
261	    }
262	    public void save(Claim claim) {
263	        jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, claim_number = ?, settled_due = ?, opened_by = ?,"
264	                + " stated = ?, stated_due = ? WHERE sheet_id = ? AND id = ?",
265	                claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getStatus().name(),
266	                claim.getNumber(), claim.getSettledDue(), claim.getOpenedBy(), claim.isStated(), claim.getStatedDue(), claim.getSheetId(), claim.getId());
267	    }
268	    /** Gives out the sheet's next claim number. The counter is raised and read in one statement, so
269	     *  claims opened at the same moment never share a number, and the number is never given again. */
270	    public int nextNumber(String sheetId) {
271	        jdbc.update("MERGE INTO sheet (id) KEY (id) VALUES (?)", sheetId);
272	        return jdbc.queryForObject("SELECT last_claim_number FROM FINAL TABLE "
273	                + "(UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = ?)", Integer.class, sheetId);
274	    }
275	}
