835	    /** The sheet's figures at one moment: people by id, in the order they were added, and the totals. */
836	    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal) {
837	        boolean sameTotals(Snapshot other) {
838	            return claimedTotal.equals(other.claimedTotal) && dueTotal.equals(other.dueTotal);
839	        }
840	    }
841	    private final PersonRepository people;
842	    private final ClaimRepository claims;
843	    private final RateRepository rates;
