853	        List<Rate> sheetRates = rates.findBySheet(sheetId);
854	        List<Claim> sheetClaims = claims.findBySheet(sheetId);
855	        Map<Long, Figures> figures = new LinkedHashMap<>();
856	        BigDecimal claimedTotal = zero();
857	        BigDecimal dueTotal = zero();
858	        for (Person person : people.findBySheet(sheetId)) {
859	            BigDecimal claimed = zero();
860	            BigDecimal due = zero();
861	            boolean fixed = false;
862	            for (Claim claim : sheetClaims) {
863	                if (claim.getPersonId() != person.getId()) continue;
864	                if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.SETTLED) continue;
