1022	/**
1023	 * Takes a statement for the person: works out their due-total as the screen shows it, binds each of
1024	 * their claims that counts (OPEN or SETTLED) to the figure it has now, unbinds the rest, and moves
1025	 * the person's statement count, last due-total and date (the sheet's today) on.
1026	 *
1027	 * A claim's figure is its settled due, else the figure a statement bound it to, else its live due at
1028	 * the person's grade's rate in force on its date (n/a without one). The due-total adds up the counting
1029	 * claims' figures, skipping n/a; it is n/a when the grade has no rate on today and no counting claim
1030	 * keeps a fixed figure.
1031	 */
1032	public class TakeStatement {
1033	    public void take(@Val Person person, ClaimRepository claims, PersonRepository people, RateRepository rateRepository,
1034	            SheetClock clock, Out<Statement> statementOut) {
1035	        String sheetId = person.getSheetId();
1036	        LocalDate today = clock.today(sheetId);
1037	        List<Rate> rates = rateRepository.findBySheet(sheetId);
1038	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
1039	        boolean fixed = false;
1040	        int counted = 0;
1041	        for (Claim claim : claims.findByPerson(sheetId, person.getId())) {
1042	            boolean counts = claim.getStatus() == ClaimStatus.OPEN || claim.getStatus() == ClaimStatus.SETTLED;
1043	            if (!counts) {
1044	                claim.setStated(false);
1045	                claim.setStatedDue(null);
1046	            } else {
1047	                BigDecimal figure = figure(claim, person, rates);
1048	                if (claim.getSettledDue() != null || (claim.isStated() && claim.getStatedDue() != null)) fixed = true;
1049	                if (figure != null) sum = sum.add(figure);
1050	                claim.setStated(true);
1051	                claim.setStatedDue(figure);
1052	                counted++;
1053	            }
1054	            claims.save(claim);
1055	        }
1056	        BigDecimal dueTotal = Rate.inForce(rates, person.getGrade(), today).isEmpty() && !fixed ? null : sum;
1057	        person.setStatementCount(person.getStatementCount() + 1);
1058	        person.setStatedTotal(dueTotal);
1059	        person.setStatementDate(today);
1060	        people.saveStatement(person);
1061	        statementOut.set(new Statement(dueTotal, counted));
1062	    }
