252	// follows the current rate.
253	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
254	export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
255	  /** Given when the claim is opened; null for a draft or a voided claim. */
256	  number: number | null;
257	  /** The due fixed when the claim was settled; null while it is live (not settled, or settled without a rate). */
258	  settledDue: string | null;
259	  /** The user who opened the claim; null until it is opened. That user may not settle it. */
260	  openedBy: string | null;
261	  /** Whether the person's last statement bound the claim to `statedDue`. */
262	  stated: boolean;
263	  /** The figure the last statement bound the claim to; null when unbound, or bound without a rate (n/a). */
264	  statedDue: string | null };
