480	/** The grade's percent in force on the date (yyyy-MM-dd): the rate with the latest from-date on or
481	 *  before it. Undefined when no rate is in force then, or the date is not known yet. */
482	export function rateOn(rates: Rate[], grade: string, date: string | undefined): string | undefined {
483	  if (date === undefined) return undefined;
484	  let best: Rate | undefined;
485	  for (const r of rates) {
486	    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
487	    if (best === undefined || (best.from ?? '') < (r.from ?? '')) best = r;
488	  }
489	  return best?.pct;
