492	/** A two-decimal string as a whole number of hundredths. */
493	export const toHundredths = (value: string): bigint => {
494	  const [whole, frac = ''] = value.split('.');
495	  return BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0') || '0');
496	};
