502	/** amount × pct / 100, rounded half to even to two decimals; n/a without a rate. Amounts are never negative. */
503	export function due(amount: string, pct: string | undefined): string {
504	  if (pct === undefined) return NA;
505	  // cents × hundredths-of-a-percent gives cents × 10000.
506	  const scaled = toHundredths(amount) * toHundredths(pct);
507	  const cents = scaled / 10000n;
508	  const rest = scaled % 10000n;
509	  return fromHundredths(rest > 5000n || (rest === 5000n && cents % 2n === 1n) ? cents + 1n : cents);
510	}
