754	}
755	import { useState } from 'react';
756	import { asString, useSearchParam } from '../../url/useSearchParam';
757	
758	// Sign in by name (no password). The signed-in name is URL state (`user`), so it survives a reload.
759	export function useCurrentUser(): [string, (user: string | undefined) => void] {
760	  return useSearchParam('user', asString);
761	}
762	
763	export function SignIn() {
764	  const [user, setUser] = useCurrentUser();
765	  const [name, setName] = useState('');
766	
767	  if (user) {
768	    return (
769	      <p>
770	        Signed in as <strong data-testid="current-user">{user}</strong>
771	      </p>
772	    );
773	  }
774	  return (
775	    <form
776	      onSubmit={(e) => {
777	        e.preventDefault();
778	        const trimmed = name.trim();
779	        if (trimmed) setUser(trimmed);
780	      }}
781	    >
782	      <label>
783	        Name <input data-testid="signin-name" value={name} onChange={(e) => setName(e.target.value)} />
784	      </label>
785	      <button type="submit" data-testid="signin-submit">
786	        Sign in
787	      </button>
788	    </form>
789	  );
790	}
791	// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
792	// of a silent `if (res.ok)` that leaves the UI showing stale data.
793	// A refused request: `reason` is the server's explanation (the response text), for the screen.
794	export class HttpError extends Error {
795	  constructor(message: string, readonly status: number, readonly reason: string) {
796	    super(message);
797	  }
798	}
799	
800	async function send<T>(path: string, init?: RequestInit): Promise<T> {
801	  const res = await fetch(path, init);
802	  if (!res.ok) {
803	    const reason = await res.text().catch(() => '');
804	    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status, reason);
805	  }
806	  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
807	}
808	
809	export function getJson<T>(path: string): Promise<T> {
810	  return send<T>(path);
811	}
