import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { HttpError, getJson, postJson, putJson } from '../../api/http';
import { useSingleSubmit } from '../../api/useSingleSubmit';
import { asNumber, useSearchParam } from '../../url/useSearchParam';
import { useCurrentUser } from '../session/SignIn';
import { ClaimedTotal, PersonClaims, claimDue, claimed, claimsKey, counts, hasFixedDue, useClaims } from '../claims/Claims';
import { NA, rateOn, total, useRates } from '../rates/Rates';
import { useSheetToday } from '../sheet/SheetToday';

// The people on the sheet, in the order they were added. One form adds a person, or edits the
// person whose editor is open (URL state `editPerson`, the person's id).
// A statement taken for a person records their due-total and binds their counting claims' figures.
export type Person = { id: number; name: string; grade: string; version: number;
  /** How many statements have been taken for the person. */
  statementCount: number;
  /** The last statement's due-total; null when none was taken, or it was n/a. */
  statedTotal: string | null;
  /** The sheet's today when the last statement was taken; null when none was. */
  statementDate: string | null };

const GRADES = ['A', 'B', 'C'];

export const peopleKey = (sheet: string) => ['sheet', sheet, 'people'];
const peoplePath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/people`;

export function usePeople(sheet: string): Person[] {
  return (
    useQuery({
      queryKey: peopleKey(sheet),
      queryFn: () => getJson<Person[]>(peoplePath(sheet)),
      enabled: !!sheet,
    }).data ?? []
  );
}

function useEditPerson() {
  return useSearchParam('editPerson', asNumber);
}

export function People({ sheet }: { sheet: string }) {
  const people = usePeople(sheet);
  const [editId, setEditId] = useEditPerson();
  // Counts each press of an Edit button, so opening the editor again reloads it with the current values.
  const [opened, setOpened] = useState(0);
  const editing = people.find((p) => p.id === editId);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const claimsOf = (p: Person) => claims.filter((c) => c.personId === p.id);
  // A person's due-total is the sum of their counted claims' already-rounded figures (0.00 with none).
  // It is n/a when their grade has no rate on the sheet's today, unless a counted claim keeps a figure
  // (settled, or bound by a statement): then it is the sum of the figures there are.
  const dueTotalOf = (p: Person) => {
    const counted = claimsOf(p).filter(counts);
    if (rateOn(rates, p.grade, today) === undefined && !counted.some(hasFixedDue)) return NA;
    return total(counted.map((c) => claimDue(c, rateOn(rates, p.grade, c.date))));
  };

  return (
    <section>
      <h2>People</h2>
      {/* Keyed so opening a person's editor (again) or closing it refills the form. */}
      <PersonForm key={editing ? `edit-${editing.id}-${opened}` : 'add'} sheet={sheet} editing={editing}
        onDone={() => setEditId(undefined)} />
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <th>Claimed</th>
            <th>Due</th>
            <th>Statements</th>
            <th>Claims</th>
            <th />
          </tr>
        </thead>
        <tbody>
          {people.map((p) => (
            <tr key={p.id} data-testid={`person-row-${p.id}`}>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{p.grade}</td>
              <td data-testid="person-claimed">{claimed(claimsOf(p))}</td>
              <td data-testid="person-due-total">{dueTotalOf(p)}</td>
              <td>
                <PersonStatement sheet={sheet} person={p} />
              </td>
              <td>
                <PersonClaims sheet={sheet} personId={p.id} claims={claimsOf(p)}
                  pctOn={(date) => rateOn(rates, p.grade, date)} />
              </td>
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => { setOpened((n) => n + 1); setEditId(p.id); }}>
                  Edit
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <ClaimedTotal sheet={sheet} />
      <p>
        Due total: <strong data-testid="rollup-due-total">{total(people.map(dueTotalOf))}</strong>
      </p>
    </section>
  );
}

/** The person's statements: how many, the last one's due-total and date, and the button that takes
 *  one. A refused statement shows the row's error, which the next statement clears. */
function PersonStatement({ sheet, person: p }: { sheet: string; person: Person }) {
  const queryClient = useQueryClient();
  const [user] = useCurrentUser();
  const by = `?user=${encodeURIComponent(user ?? '')}`;
  const take = useMutation({
    mutationFn: () => postJson<Person>(`${peoplePath(sheet)}/${p.id}/statement${by}`, {}),
    onSuccess: () => Promise.all([
      queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
      queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
    ]),
  });
  return (
    <>
      <span data-testid="person-statement-count">{p.statementCount}</span>{' '}
      Last <span data-testid="person-stated-total">{p.statementCount > 0 ? p.statedTotal ?? NA : ''}</span>{' '}
      on <span data-testid="person-statement-date">{p.statementDate ?? ''}</span>{' '}
      <button type="button" data-testid="person-statement" disabled={take.isPending}
        onClick={() => { take.reset(); take.mutate(); }}>
        Statement
      </button>
      {take.isError && (
        <span role="alert" data-testid="person-error">
          {' '}
          {(take.error instanceof HttpError && take.error.reason) || 'The statement could not be taken.'}
        </span>
      )}
    </>
  );
}

function PersonForm({ sheet, editing, onDone }: { sheet: string; editing?: Person; onDone: () => void }) {
  const queryClient = useQueryClient();
  const [name, setName] = useState(editing?.name ?? '');
  const [grade, setGrade] = useState(editing?.grade ?? 'A');
  // The version of the person the editor loaded; the server refuses the save (409) when someone
  // else has saved the person since.
  const [version, setVersion] = useState(editing?.version);
  const [user] = useCurrentUser();
  const by = `?user=${encodeURIComponent(user ?? '')}`;
  const submitOnce = useSingleSubmit();
  const save = useMutation({
    mutationFn: (body: { name: string; grade: string; version?: number }) =>
      editing
        ? putJson<Person>(`${peoplePath(sheet)}/${editing.id}${by}`, body)
        : postJson<Person>(`${peoplePath(sheet)}${by}`, body),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
      if (editing) {
        onDone();
      } else {
        setName('');
        setGrade('A');
      }
    },
    onError: (error) => {
      if (!(editing && error instanceof HttpError && error.status === 409)) return;
      // Someone else saved the person: re-read the sheet and show the current values in the form.
      void queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }).then(() => {
        const current = queryClient.getQueryData<Person[]>(peopleKey(sheet))?.find((p) => p.id === editing.id);
        if (!current) return;
        setName(current.name);
        setGrade(current.grade);
        setVersion(current.version);
      });
    },
  });

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        submitOnce(() => {
          save.reset();
          // A blank or already-used name is refused by the server (400), which shows the form's error.
          return save.mutateAsync({ name, grade, version });
        });
      }}
    >
      <label>
        Name{' '}
        <input
          data-testid="person-form-name"
          value={name}
          onChange={(e) => {
            save.reset();
            setName(e.target.value);
          }}
        />
      </label>{' '}
      <label>
        Grade{' '}
        <select
          data-testid="person-form-grade"
          value={grade}
          onChange={(e) => {
            save.reset();
            setGrade(e.target.value);
          }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
      </label>{' '}
      <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
        {editing ? 'Save' : 'Add'}
      </button>
      {editing && (
        <button type="button" onClick={onDone}>
          Cancel
        </button>
      )}
      {save.isError && (
        <span role="alert" data-testid="person-form-error">
          {' '}
          {(save.error instanceof HttpError && (save.error.status === 400 || save.error.status === 409) && save.error.reason)
            || 'The person could not be saved.'}
        </span>
      )}
    </form>
  );
}
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { HttpError, getJson, postJson, putJson } from '../../api/http';
import { useSingleSubmit } from '../../api/useSingleSubmit';
import { asNumber, useSearchParam } from '../../url/useSearchParam';
import { useCurrentUser } from '../session/SignIn';
import { useSheetToday } from '../sheet/SheetToday';
import { NA, due } from '../rates/Rates';

// A person's claims, listed under their row newest first. One form per row adds a claim, or edits
// the claim whose editor is open (URL state `editClaim`, the claim's id). Amounts come from the
// server as strings with two decimals and are added up in whole cents, never as floats. A claim's
// status moves DRAFT -> OPEN -> SETTLED, or DRAFT/OPEN -> VOID; the server refuses any other change.
// Opening gives a claim the sheet's next number, which voiding clears; a draft has none.
// The user who opens a claim is recorded and may not settle it.
// Settling fixes a claim's due at the rate of that moment. A person's statement binds each of their
// counting claims to the figure it has then, until their next statement; every other claim's due
// follows the current rate.
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  /** Given when the claim is opened; null for a draft or a voided claim. */
  number: number | null;
  /** The due fixed when the claim was settled; null while it is live (not settled, or settled without a rate). */
  settledDue: string | null;
  /** The user who opened the claim; null until it is opened. That user may not settle it. */
  openedBy: string | null;
  /** Whether the person's last statement bound the claim to `statedDue`. */
  stated: boolean;
  /** The figure the last statement bound the claim to; null when unbound, or bound without a rate (n/a). */
  statedDue: string | null };

const ACTIONS = [
  { action: 'open', label: 'Open' },
  { action: 'settle', label: 'Settle' },
  { action: 'void', label: 'Void' },
];

type ClaimBody = { amount: string; date: string; note: string };

export const claimsKey = (sheet: string) => ['sheet', sheet, 'claims'];
const sheetPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}`;

export function useClaims(sheet: string): Claim[] {
  return (
    useQuery({
      queryKey: claimsKey(sheet),
      queryFn: () => getJson<Claim[]>(`${sheetPath(sheet)}/claims`),
      enabled: !!sheet,
    }).data ?? []
  );
}

const toCents = (amount: string) => {
  const [whole, frac = ''] = amount.split('.');
  return Number(whole) * 100 + Number(frac.padEnd(2, '0'));
};

/** Only OPEN and SETTLED claims count toward claimed, due-total and every total. */
export const counts = (c: Claim) => c.status === 'OPEN' || c.status === 'SETTLED';

/** A claim's figure: the due fixed when it was settled, else the figure a statement bound it to, else
 *  its live due at `pct` (n/a without one). */
export const claimDue = (c: Claim, pct: string | undefined): string =>
  c.settledDue ?? (c.stated ? c.statedDue ?? NA : due(c.amount, pct));

/** Whether the claim keeps a figure of its own, whatever the rates: settled, or bound by a statement. */
export const hasFixedDue = (c: Claim) => c.settledDue !== null || (c.stated && c.statedDue !== null);

/** The counted claims' amounts added up, with two decimals. */
export function claimed(claims: Claim[]): string {
  const cents = claims.filter(counts).reduce((sum, c) => sum + toCents(c.amount), 0);
  return `${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
}

export function ClaimedTotal({ sheet }: { sheet: string }) {
  const claims = useClaims(sheet);
  return (
    <p>
      Claimed total: <strong data-testid="rollup-claimed-total">{claimed(claims)}</strong>
    </p>
  );
}

/** The claims cell of a person's row: the claim form and the person's claims, newest first, each
 *  with its due at the person's grade's rate in force on its date (`pctOn`, undefined when none is). */
export function PersonClaims({ sheet, personId, claims, pctOn }: {
  sheet: string; personId: number; claims: Claim[]; pctOn: (date: string) => string | undefined;
}) {
  const [editId, setEditId] = useSearchParam('editClaim', asNumber);
  const editing = claims.find((c) => c.id === editId);

  return (
    <>
      {/* Keyed so opening another claim's editor (or closing it) refills the form. */}
      <ClaimForm key={editing ? `edit-${editing.id}` : 'add'} sheet={sheet} personId={personId}
        editing={editing} onDone={() => setEditId(undefined)} />
      <ul>
        {claims.map((c) => (
          <ClaimRow key={c.id} sheet={sheet} claim={c} pct={pctOn(c.date)} onEdit={() => setEditId(c.id)} />
        ))}
      </ul>
    </>
  );
}

/** One claim: its fields, status and due, with its edit and status buttons. A refused status change
 *  shows the row's error, which the row's next action clears. */
function ClaimRow({ sheet, claim: c, pct, onEdit }: {
  sheet: string; claim: Claim; pct: string | undefined; onEdit: () => void;
}) {
  const queryClient = useQueryClient();
  const [user] = useCurrentUser();
  const by = `?user=${encodeURIComponent(user ?? '')}`;
  const change = useMutation({
    mutationFn: (action: string) => postJson<Claim>(`${sheetPath(sheet)}/claims/${c.id}/${action}${by}`, {}),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
  });

  return (
    <li data-testid={`claim-row-${c.id}`}>
      #<span data-testid="claim-number">{c.number ?? ''}</span>{' '}
      <span data-testid="claim-amount">{c.amount}</span>{' '}
      <span data-testid="claim-date">{c.date}</span>{' '}
      <span data-testid="claim-note">{c.note}</span>{' '}
      <span data-testid="claim-status">{c.status}</span>{' '}
      Opened by <span data-testid="claim-opened-by">{c.openedBy ?? ''}</span>{' '}
      Due <span data-testid="claim-due">{claimDue(c, pct)}</span>{' '}
      Stated <span data-testid="claim-stated">{c.stated ? 'yes' : 'no'}</span>{' '}
      <button type="button" data-testid="claim-edit" onClick={() => { change.reset(); onEdit(); }}>
        Edit
      </button>
      {ACTIONS.map(({ action, label }) => (
        <button key={action} type="button" data-testid={`claim-${action}`} disabled={change.isPending}
          onClick={() => { change.reset(); change.mutate(action); }}>
          {label}
        </button>
      ))}
      {change.isError && (
        <span role="alert" data-testid="claim-error">
          {' '}
          {(change.error instanceof HttpError && change.error.reason) || 'The claim could not be changed.'}
        </span>
      )}
    </li>
  );
}

function ClaimForm({ sheet, personId, editing, onDone }: {
  sheet: string; personId: number; editing?: Claim; onDone: () => void;
}) {
  const queryClient = useQueryClient();
  const today = useSheetToday(sheet);
  const [amount, setAmount] = useState(editing?.amount ?? '');
  // Undefined until changed: the sheet's today, which the server fills in when the date is blank.
  const [date, setDate] = useState<string | undefined>(editing?.date);
  const [note, setNote] = useState(editing?.note ?? '');
  const [user] = useCurrentUser();
  const by = `?user=${encodeURIComponent(user ?? '')}`;
  const submitOnce = useSingleSubmit();
  const save = useMutation({
    mutationFn: (body: ClaimBody) =>
      editing
        ? putJson<Claim>(`${sheetPath(sheet)}/claims/${editing.id}${by}`, body)
        : postJson<Claim>(`${sheetPath(sheet)}/people/${personId}/claims${by}`, body),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
      if (editing) {
        onDone();
      } else {
        setAmount('');
        setDate(undefined);
        setNote('');
      }
    },
  });
  const changed = <T,>(set: (v: T) => void) => (v: T) => {
    save.reset();
    set(v);
  };

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        submitOnce(() => {
          save.reset();
          // A missing, negative or over-precise amount is refused by the server (400).
          return save.mutateAsync({ amount, date: date ?? '', note });
        });
      }}
    >
      <input data-testid="claim-form-amount" placeholder="Amount" inputMode="decimal" value={amount}
        onChange={(e) => changed(setAmount)(e.target.value)} />{' '}
      <input type="date" data-testid="claim-form-date" value={date ?? today ?? ''}
        onChange={(e) => changed(setDate)(e.target.value)} />{' '}
      <input data-testid="claim-form-note" placeholder="Note" value={note}
        onChange={(e) => changed(setNote)(e.target.value)} />{' '}
      <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
        {editing ? 'Save claim' : 'Add claim'}
      </button>
      {editing && (
        <button type="button" onClick={onDone}>
          Cancel
        </button>
      )}
      {save.isError && (
        <span role="alert" data-testid="claim-form-error">
          {' '}
          {(save.error instanceof HttpError && save.error.status === 400 && save.error.reason)
            || 'The claim could not be saved.'}
        </span>
      )}
    </form>
  );
}
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { HttpError, getJson, putJson } from '../../api/http';
import { useSingleSubmit } from '../../api/useSingleSubmit';
import { useCurrentUser } from '../session/SignIn';
import { useSheetToday } from '../sheet/SheetToday';

// The sheet's rates for each grade: a percent with two decimals, set here, each in force from its
// from-date (null: from the beginning of time). A claim uses its grade's rate in force on its date;
// with none it shows n/a, and so does anything due that depends on it. Money and percents come from
// the server as strings with two decimals and are worked in whole cents and hundredths of a percent,
// never floats.
export type Rate = { grade: string; pct: string; from: string | null };

const GRADES = ['A', 'B', 'C'];
export const NA = 'n/a';

export const ratesKey = (sheet: string) => ['sheet', sheet, 'rates'];
const ratesPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/rates`;

export function useRates(sheet: string): Rate[] {
  return (
    useQuery({
      queryKey: ratesKey(sheet),
      queryFn: () => getJson<Rate[]>(ratesPath(sheet)),
      enabled: !!sheet,
    }).data ?? []
  );
}

/** The grade's percent in force on the date (yyyy-MM-dd): the rate with the latest from-date on or
 *  before it. Undefined when no rate is in force then, or the date is not known yet. */
export function rateOn(rates: Rate[], grade: string, date: string | undefined): string | undefined {
  if (date === undefined) return undefined;
  let best: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (best === undefined || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  return best?.pct;
}

/** A two-decimal string as a whole number of hundredths. */
export const toHundredths = (value: string): bigint => {
  const [whole, frac = ''] = value.split('.');
  return BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0') || '0');
};

/** Hundredths as a two-decimal string. */
export const fromHundredths = (h: bigint): string =>
  `${h / 100n}.${String(h % 100n).padStart(2, '0')}`;

/** amount × pct / 100, rounded half to even to two decimals; n/a without a rate. Amounts are never negative. */
export function due(amount: string, pct: string | undefined): string {
  if (pct === undefined) return NA;
  // cents × hundredths-of-a-percent gives cents × 10000.
  const scaled = toHundredths(amount) * toHundredths(pct);
  const cents = scaled / 10000n;
  const rest = scaled % 10000n;
  return fromHundredths(rest > 5000n || (rest === 5000n && cents % 2n === 1n) ? cents + 1n : cents);
}

/** Two-decimal values added up, skipping n/a. */
export function total(values: string[]): string {
  return fromHundredths(values.filter((v) => v !== NA).reduce((sum, v) => sum + toHundredths(v), 0n));
}

export function Rates({ sheet }: { sheet: string }) {
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  return (
    <section>
      <h2>Rates</h2>
      <RateForm sheet={sheet} />
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>Rate % today</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => (
            <tr key={g}>
              <td>{g}</td>
              <td data-testid={`rate-current-${g}`}>{rateOn(rates, g, today) ?? NA}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>From</th>
            <th>Rate %</th>
          </tr>
        </thead>
        <tbody>
          {rates.map((r) => (
            <tr key={`${r.grade}-${r.from ?? 'start'}`} data-testid={`rate-row-${r.grade}-${r.from ?? 'start'}`}>
              <td>{r.grade}</td>
              <td>{r.from ?? 'start'}</td>
              <td data-testid="rate-pct">{r.pct}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

function RateForm({ sheet }: { sheet: string }) {
  const queryClient = useQueryClient();
  const [grade, setGrade] = useState('A');
  const [pct, setPct] = useState('');
  const [from, setFrom] = useState('');
  const [user] = useCurrentUser();
  const by = `?user=${encodeURIComponent(user ?? '')}`;
  const submitOnce = useSingleSubmit();
  const save = useMutation({
    mutationFn: (body: { grade: string; pct: string; from: string }) =>
      putJson<Rate>(`${ratesPath(sheet)}/${encodeURIComponent(body.grade)}${by}`, { pct: body.pct, from: body.from }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ratesKey(sheet) });
      setPct('');
      setFrom('');
    },
  });

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        submitOnce(() => {
          save.reset();
          // A missing, out-of-range or over-precise percent, or a from-date that is not a date, is
          // refused by the server (400). A blank from-date sets the rate in force from the beginning.
          return save.mutateAsync({ grade, pct, from: from.trim() });
        });
      }}
    >
      <label>
        Grade{' '}
        <select
          data-testid="rate-form-grade"
          value={grade}
          onChange={(e) => {
            save.reset();
            setGrade(e.target.value);
          }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
      </label>{' '}
      <label>
        Rate %{' '}
        <input
          data-testid="rate-form-pct"
          inputMode="decimal"
          value={pct}
          onChange={(e) => {
            save.reset();
            setPct(e.target.value);
          }}
        />
      </label>{' '}
      <label>
        From{' '}
        <input
          type="date"
          data-testid="rate-form-from"
          value={from}
          onChange={(e) => {
            save.reset();
            setFrom(e.target.value);
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
        Set rate
      </button>
      {save.isError && (
        <span role="alert" data-testid="rate-form-error">
          {' '}
          {(save.error instanceof HttpError && save.error.status === 400 && save.error.reason)
            || 'The rate could not be saved.'}
        </span>
      )}
    </form>
  );
}
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson, putJson } from '../../api/http';
import { useSingleSubmit } from '../../api/useSingleSubmit';
import { useCurrentUser } from '../session/SignIn';

// The sheet's "today" (yyyy-MM-dd). It starts as the real date and is changed here. Anything that
// depends on the date, or defaults a date, reads it with useSheetToday — never the browser clock.
type Today = { today: string };

const todayKey = (sheet: string) => ['sheet', sheet, 'today'];
const todayPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/today`;

export function useSheetToday(sheet: string): string | undefined {
  return useQuery({
    queryKey: todayKey(sheet),
    queryFn: () => getJson<Today>(todayPath(sheet)),
    enabled: !!sheet,
  }).data?.today;
}

export function SheetToday({ sheet }: { sheet: string }) {
  const today = useSheetToday(sheet);
  const queryClient = useQueryClient();
  const [date, setDate] = useState('');
  const [user] = useCurrentUser();
  const submitOnce = useSingleSubmit();
  const save = useMutation({
    mutationFn: (value: string) =>
      putJson<Today>(`${todayPath(sheet)}?user=${encodeURIComponent(user ?? '')}`, { today: value }),
    onSuccess: (saved) => {
      queryClient.setQueryData(todayKey(sheet), saved);
      void queryClient.invalidateQueries({ queryKey: ['sheet', sheet] });
    },
  });

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        submitOnce(() => {
          save.reset();
          return save.mutateAsync(date.trim());
        });
      }}
    >
      Today: <strong data-testid="sheet-today">{today}</strong>{' '}
      <label>
        Set today{' '}
        <input
          type="date"
          data-testid="sheet-today-input"
          value={date}
          onChange={(e) => {
            save.reset();
            setDate(e.target.value);
          }}
        />
      </label>
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Save
      </button>
      {save.isError && (
        <span role="alert" data-testid="sheet-today-error">
          {' '}Not a valid date.
        </span>
      )}
    </form>
  );
}
import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { asString, useSearchParam } from '../../url/useSearchParam';

// Choose the active sheet by id. The active sheet is URL state (`sheet`); everything else is kept
// per sheet, under query keys starting ['sheet', id]. Loading an id (again) re-reads it from the store.
export function useSheetId(): string {
  return useSearchParam('sheet', asString)[0];
}

export function SheetPicker() {
  const [sheet, setSheet] = useSearchParam('sheet', asString);
  const [id, setId] = useState('');
  const queryClient = useQueryClient();

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        const trimmed = id.trim();
        if (!trimmed) return;
        setSheet(trimmed);
        void queryClient.invalidateQueries({ queryKey: ['sheet', trimmed] });
      }}
    >
      <label>
        Sheet <input data-testid="sheet-id-input" value={id} onChange={(e) => setId(e.target.value)} />
      </label>
      <button type="submit" data-testid="sheet-load">
        Load
      </button>
      {sheet && (
        <span>
          {' '}Active sheet: <strong data-testid="sheet-current-id">{sheet}</strong>
        </span>
      )}
    </form>
  );
}
import { useState } from 'react';
import { asString, useSearchParam } from '../../url/useSearchParam';

// Sign in by name (no password). The signed-in name is URL state (`user`), so it survives a reload.
export function useCurrentUser(): [string, (user: string | undefined) => void] {
  return useSearchParam('user', asString);
}

export function SignIn() {
  const [user, setUser] = useCurrentUser();
  const [name, setName] = useState('');

  if (user) {
    return (
      <p>
        Signed in as <strong data-testid="current-user">{user}</strong>
      </p>
    );
  }
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        const trimmed = name.trim();
        if (trimmed) setUser(trimmed);
      }}
    >
      <label>
        Name <input data-testid="signin-name" value={name} onChange={(e) => setName(e.target.value)} />
      </label>
      <button type="submit" data-testid="signin-submit">
        Sign in
      </button>
    </form>
  );
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
// A refused request: `reason` is the server's explanation (the response text), for the screen.
export class HttpError extends Error {
  constructor(message: string, readonly status: number, readonly reason: string) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    const reason = await res.text().catch(() => '');
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status, reason);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
